sections.body:
保存为 guarded-plan.mjs，运行 node guarded-plan.mjs。makeRunner 接收模型候选的 JSON 字符串；每次调用返回新状态，不修改传入对象。实际项目须把返回状态交给唯一的游戏状态持有者，本例只是同步模拟器。

```js
/**
 * @file A synchronous workshop simulator with guarded plan execution.
 * @author liliwei
 * @date 2026-10-29
 * @LastEditors liliwei
 * @LastEditTime 2026-10-29
 */
/** Check an authoritative toy-world snapshot. @param {object} s World. @returns {void} */
function checkWorld(s) {
  if (!s || typeof s !== 'object' || Array.isArray(s) ||
      !['wood', 'plank'].every(k => Number.isSafeInteger(s[k]) && s[k] >= 0) ||
      typeof s.benchOpen !== 'boolean' || typeof s.delivered !== 'boolean') {
    throw new TypeError('Invalid world');
  }
}
const skills = {
  craft: {
    /** @param {object} s Current world. @returns {boolean} Whether crafting is legal. */
    can: s => s.benchOpen && s.wood >= 2 && s.plank < Number.MAX_SAFE_INTEGER,
    /** @param {object} s Current world. @returns {object} Committed toy-world state. */
    apply: s => ({ ...s, wood: s.wood - 2, plank: s.plank + 1 })
  },
  deliver: {
    /** @param {object} s Current world. @returns {boolean} Whether delivery is legal. */
    can: s => s.plank >= 1,
    /** @param {object} s Current world. @returns {object} Committed toy-world state. */
    apply: s => ({ ...s, plank: s.plank - 1, delivered: true })
  }
};
/** Parse a bounded plan. @param {string} raw JSON text. @returns {Function} One-step runner. */
export function makeRunner(raw) {
  if (typeof raw !== 'string' || raw.length > 2048) throw new TypeError('Invalid plan text');
  const p = JSON.parse(raw);
  if (!p || typeof p !== 'object' || Array.isArray(p) ||
      Object.keys(p).sort().join(',') !== 'ruleVersion,steps' ||
      p.ruleVersion !== 'workshop-v1' || !Array.isArray(p.steps) || p.steps.length > 4 ||
      !p.steps.every(id => typeof id === 'string' && Object.hasOwn(skills, id))) {
    throw new TypeError('Invalid plan');
  }
  const steps = [...p.steps];
  let cursor = 0, stopped = false;
  /** Advance once using fresh state. @param {object} s World. @returns {object} Status and new state. */
  return function step(s) {
    checkWorld(s);
    const state = { ...s };
    if (stopped) return { status: 'stopped', state };
    if (state.delivered) { stopped = true; return { status: 'success', state }; }
    if (cursor === steps.length) { stopped = true; return { status: 'incomplete', state }; }
    const id = steps[cursor], skill = skills[id];
    if (!skill.can(state)) {
      stopped = true;
      return { status: 'blocked', action: id, state };
    }
    const next = skill.apply(state);
    checkWorld(next);
    cursor++;
    const status = next.delivered ? 'success' : cursor === steps.length ? 'incomplete' : 'running';
    stopped = status !== 'running';
    return { status, action: id, state: next };
  };
}
const plan = JSON.stringify({ ruleVersion: 'workshop-v1', steps: ['craft', 'deliver'] });
const start = { wood: 2, plank: 0, benchOpen: true, delivered: false };
const normal = makeRunner(plan);
const first = normal(start);
console.log('normal', first.status, normal(first.state).status);
const interrupted = makeRunner(plan);
const made = interrupted(start);
const changed = { ...made.state, plank: 0 }; // 另一角色拿走木板
console.log('interrupted', made.status, interrupted(changed).status);
```

正文代码在 Node.js 22.16.0 原样运行：normal 输出 running、success；interrupted 输出 running、blocked。正常交付后 wood=0、plank=0、delivered=true；木板被拿走时保持 plank=0、delivered=false。停止后的执行器再次收到状态只返回 stopped，恢复资源后也要显式创建新计划。

数组用完但订单未完成时返回 incomplete；交付完成就停止，计划尾部的重复交付不会继续执行。本例仅针对一个订单。真实多订单要按 orderId 保存完成标记，不能共用一个全局布尔值。

这里的 apply 就是玩具世界的同步结算，并非异步引擎接口；代码没有实现寻路、动作完成后的权威回读、取消或服务器事务。这些差距要在接入时补上，不能把本次规则测试当作联机正确性证明。
